def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"]]
    result = sum(values) / len(values)
    return {
        "value": result,
        "trace": {
            "values": values,
            "count": len(values),
            "sum": sum(values),
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
